import { CanvasCore } from './CanvasCore';
import { Core } from './Core/Core';
import { Implementation } from './Implementation';

// https://gamedevelopment.tutsplus.com/tutorials/basic-2d-platformer-physics-part-1--cms-25799

export class AppRigidBodyDynamics {
    canvasCore: CanvasCore;
    core: Core;
    implementation: Implementation;
    static Init(id: string) {
        const n = new AppRigidBodyDynamics(id);
        n.Dummy();
    }
    constructor(id: string = 'SandBox') {
        this.canvasCore = new CanvasCore(id);
        this.core = new Core(this.canvasCore);
        this.implementation = new Implementation();
        this.BindEvent();
        this.BindRenderer();
    }
    Dummy() {
        //
    }
    BindEvent() {
        this.canvasCore.MouseDown = (e: MouseEvent) => this.implementation.MouseDown(e);
        this.canvasCore.MouseMove = (e: MouseEvent) => this.implementation.MouseMove(e);
        this.canvasCore.MouseUp = (e: MouseEvent) => this.implementation.MouseUp(e);
    }
    BindRenderer() {
        this.canvasCore.Render = (ctx: CanvasRenderingContext2D) => this.implementation.Render(ctx);
    }
}


export class Solution {
    public divHost: HTMLElement;

    constructor(id: string) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        AppRigidBodyDynamics.Init(id)
    }
    public destroy() {
        if (this.divHost) {
            try {
                while (this.divHost.firstChild) {
                    this.divHost.removeChild(this.divHost.firstChild);
                }
            } catch (error) {
                console.error('Error in destroy method:', error);
            }
        } else {
            console.warn('divHost is undefined in destroy method');
        }
    }
}