import { Graph } from './Core/Graph';
import { NVector3 } from '../../lib';
export class ParticleSystemC {
    public particles: Graph[] = [];
    public t = 0.6;
    public m: NVector3 = new NVector3(10, 10, 10);
    boundingBox: DOMRect
    constructor() {
        this.particles.push(new Graph(new NVector3(0, 0, 0)));
        this.particles.push(new Graph(new NVector3(10, 10, 0)));

        console.log('particle system');
    }
    public Render(ctx: CanvasRenderingContext2D) {
        this.boundingBox = ctx.canvas.getBoundingClientRect();

        // console.log(ctx);
        for (let i = 0; i < this.particles.length; ++i) {
            this.particles[i].Move(this.m, 0.9, -1.5, this.t);
            this.particles[i].Render(ctx);
        }

        ctx.fillStyle = '#ff0000';
        ctx.beginPath();
        ctx.arc(this.m.x, this.m.y, 0.5, 0, Math.PI * 2);
        ctx.closePath();
        ctx.fill();

    }
    MouseDown(e: MouseEvent) {
        // console.log(e);
    }
    MouseUp(e: MouseEvent) {
        // console.log(e);
    }
    MouseMove(e: MouseEvent) {
        // console.log(e, this.ctx.canvas);
        // this.m.x = (e.x - 100) * 0.1;
        // this.m.y = (e.y - 200) * 0.1;

        // this.m.x = (e.x - this.ctx.canvas.offsetLeft ) * 0.1;
        // this.m.y = (e.y - this.ctx.canvas.offsetTop) * 0.1;

        this.m.x = e.x - this.boundingBox.left;
        this.m.y = e.y - this.boundingBox.top;
    }
}